import math
values = [100.0, None, 0.0, float("nan"), float("inf"), 102.0]
reasons = []
accepted = []
for index, value in enumerate(values):
    if value is None:
        reasons.append((index, "missing"))
    elif type(value) is not float:
        reasons.append((index, "type"))
    elif not math.isfinite(value):
        reasons.append((index, "nonfinite"))
    elif value <= 0:
        reasons.append((index, "nonpositive"))
    else:
        accepted.append(value)
print(accepted)
print(reasons)
print(len(accepted) + len(reasons))
